unsigned ShapeNear(const ShapeHints &hints, unsigned remaining) {
    if (!hints.count || !remaining) return 0;
    unsigned best = 0;
    for (unsigned subset = 1; subset < (1u << hints.count); ++subset) {
        if (unsigned(__builtin_popcount(subset)) > remaining) continue;
        unsigned value = 0; bool compatible = true;
        for (unsigned a = 0; a < hints.count && compatible; ++a) if (subset & (1u << a)) {
            value += hints.items[a].value;
            for (unsigned b = a + 1; b < hints.count; ++b) if (subset & (1u << b)) {
                const auto &x = hints.items[a]; const auto &y = hints.items[b];
                if ((x.cells & y.cells) || (x.color == y.color && (x.border & y.cells))) compatible = false;
            }
        }
        if (compatible) best = std::max(best, value);
    }
    return best;
}
